package workspaces

import (
	"fmt"
	"sort"
	"strings"

	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"

	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// minFuzzyQueryLen is the threshold below which the prompt runs no query: a
// subsequence match over a whole directory tree returns too much to be
// useful on one or two characters, and running it on every keystroke below
// that would be wasted work besides.
const minFuzzyQueryLen = 3

// FuzzyFindCancelMsg is sent when the user backs out of the fuzzy-find
// prompt without picking a result.
type FuzzyFindCancelMsg struct{}

// FuzzyFindConfirmMsg carries the absolute path of the directory chosen from
// the fuzzy-find results.
type FuzzyFindConfirmMsg struct {
	Path string
}

// fuzzyRow is one line of the results table.
type fuzzyRow struct {
	Candidate fuzzyCandidate
}

// FuzzyFinder is the "g" prompt: a query, and the whole-tree directories
// that match it, ranked. It owns its own key handling while active — the
// same shape as WorkspaceInput — and a datatable.Model purely for rendering
// and cursor movement over an already-ranked list. The table's own sort and
// "/" filter bar are never reached: only navigation keys are ever forwarded
// to it (see Update), and the order shown is the scorer's, not the table's.
type FuzzyFinder struct {
	query      textinput.Model
	loading    bool
	candidates []fuzzyCandidate
	skipped    int
	results    datatable.Model[fuzzyRow]
}

// NewFuzzyFinder creates the prompt, focused, with an empty result set — the
// whole-tree walk behind it is kicked off separately as a Cmd
// (Model.walkWorkspaceDirsCmd), so its I/O never runs inside Update or View
// (Rule 110).
func NewFuzzyFinder() *FuzzyFinder {
	ti := textinput.New()
	ti.Placeholder = "type at least 3 characters"
	ti.Focus()
	ti.CharLimit = 200
	ti.Width = 60
	theme.StyleTextInput(&ti)

	return &FuzzyFinder{
		query:   ti,
		loading: true,
		results: datatable.New(datatable.Config[fuzzyRow]{
			Columns:    fuzzyColumns(),
			SortColumn: -1, // ranked by score, not by the table's own comparator
		}),
	}
}

func fuzzyColumns() []datatable.Column[fuzzyRow] {
	return []datatable.Column[fuzzyRow]{
		{
			Title: "", Sizing: datatable.SizingFixed, MinWidth: datatable.IconColumnWidth,
			Cell:  func(r fuzzyRow) string { return theme.IconDirectory },
			Style: func(r fuzzyRow) lipgloss.Style { return theme.IconStyle(theme.IconRoleDirectory) },
		},
		{
			Title: "Path", Sizing: datatable.SizingContent, TruncateHead: true, MinWidth: 20, Flex: 1,
			Cell: func(r fuzzyRow) string { return r.Candidate.Rel },
		},
	}
}

// SetCandidates records the whole-tree walk's result and reranks the current
// query over it, if one is long enough to run.
func (f *FuzzyFinder) SetCandidates(candidates []fuzzyCandidate, skipped int) {
	f.loading = false
	f.candidates = candidates
	f.skipped = skipped
	f.rematch()
}

// Resize adapts the prompt to the viewport, mirroring updateTableSize
// exactly — the query lives in the footer's bar slot now (RenderBar), so
// the results table is the whole viewport, the same as the normal browse
// table.
func (f *FuzzyFinder) Resize(width, height int) {
	f.results.Resize(width, max(height-1, 1))
}

// Update handles input while the prompt is active.
func (f *FuzzyFinder) Update(msg tea.Msg) (*FuzzyFinder, tea.Cmd) {
	if key, ok := msg.(tea.KeyMsg); ok {
		switch key.String() {
		case "esc":
			return f, func() tea.Msg { return FuzzyFindCancelMsg{} }
		case "enter":
			if row, ok := f.results.Selected(); ok {
				path := row.Candidate.Abs
				return f, func() tea.Msg { return FuzzyFindConfirmMsg{Path: path} }
			}
			return f, nil
		case "up", "down", "pgup", "pgdown", "home", "end":
			f.results.Update(msg)
			return f, nil
		}
	}

	before := f.query.Value()
	var cmd tea.Cmd
	f.query, cmd = f.query.Update(msg)
	if f.query.Value() != before {
		f.rematch()
	}
	return f, cmd
}

// rematch reranks the loaded candidates against the current query. Below the
// 3-character threshold, or before the walk has landed, the results table is
// simply empty — StatusText says why.
func (f *FuzzyFinder) rematch() {
	query := strings.TrimSpace(f.query.Value())
	if f.loading || len(query) < minFuzzyQueryLen {
		f.results.SetItems(nil)
		return
	}

	type scored struct {
		row   fuzzyRow
		score int
	}
	matches := make([]scored, 0, len(f.candidates))
	for _, c := range f.candidates {
		if score, ok := matchFuzzy(c.Rel, query); ok {
			matches = append(matches, scored{row: fuzzyRow{Candidate: c}, score: score})
		}
	}
	sort.SliceStable(matches, func(i, j int) bool { return matches[i].score > matches[j].score })

	rows := make([]fuzzyRow, len(matches))
	for i, m := range matches {
		rows[i] = m.row
	}
	f.results.SetItems(rows)
	f.results.Remeasure()
	f.results.GotoTop()
}

// StatusText is the footer's one line while the prompt is open.
func (f *FuzzyFinder) StatusText() string {
	switch {
	case f.loading:
		return "Scanning workspace directories..."
	case len(strings.TrimSpace(f.query.Value())) < minFuzzyQueryLen:
		return "Type at least 3 characters to search"
	default:
		return ""
	}
}

// matchHint is the bar's inline count, the same role goto's "1-N" plays.
func (f *FuzzyFinder) matchHint() string {
	query := strings.TrimSpace(f.query.Value())
	if f.loading || len(query) < minFuzzyQueryLen {
		return ""
	}
	return fmt.Sprintf("%d match(es)", len(f.results.Items()))
}

// RenderBar draws the query in the filter bar's own frame — the same slot
// and the same components.BarFrame the "/" filter and the viewer's own "g"
// (go to line) already use, so the rectangle that closes the viewport is
// the same one whichever occupies it.
func (f *FuzzyFinder) RenderBar(width int) string {
	inner := theme.Bg(" ") + theme.KeyStyle.Render("Find") +
		theme.Bg(" ") + theme.DimStyle.Render(theme.IconChevronRight) + theme.Bg(" ") +
		f.query.View()
	if hint := f.matchHint(); hint != "" {
		inner += theme.Bg("  ") + theme.DimStyle.Render(hint)
	}
	return sharedcomponents.BarFrame(width, inner)
}

// View renders the ranked results — the whole viewport, now that the query
// lives in the footer's bar slot (RenderBar).
func (f *FuzzyFinder) View() string {
	return f.results.View()
}
Two things make the directory's count **partial**, and both render the same `?`:
a sub-repository whose cache entry has no summary (nobody read it for
misconfigurations), and one nobody has scanned at all — the second is the same
condition that already pushes a `SecretsUnknown` into `foldSecrets`. The
directory cannot be more certain than what is unknown about its children.

`misconfigCell` carries `Text`, `State` and `Worst` separately, on
`secretsCell`'s model: the text has cases the state does not — a file and a
directory holding no repository print nothing at all, while a repository waiting
for a scan prints a dash — and all of them colour dim.

## Fuzzy find (`g`)

`g` opens a prompt (`FuzzyFinder`, `fuzzyfind.go`): type at least 3
characters and a ranked list of directories anywhere under the workspaces
root appears, `Enter` on one drills there. The view has no tree in memory —
`currentPath`/`navigationStack`/`cursorStack` describe one listing at a
time (drill-down, above) — so a jump is not a lookup into existing state on
either side of it:

- **Finding candidates** (`fuzzywalk.go`) is a fresh whole-tree walk every
  time the prompt opens, run as a `Cmd` and reported back as
  `FuzzyPathsLoadedMsg`. `walkAllDirs` shares `isHidden`, `leadsToDir`,
  `mayFollow` and `holdsRepo` with `walkSubRepos` above — the same cycle
  guard, the same junction handling — and stops at the same boundary: it
  finds a repository and records it, but does not walk *into* one. A
  repository is a valid target to jump to; its own `node_modules` or
  `vendor` is not a candidate, for the same reason it is never a scan
  target on its own.
- **Ranking** (`fuzzymatch.go`) is a plain subsequence match with no
  dependency behind it — none existed anywhere in this codebase before this
  — scored higher for a consecutive run of matched characters and for a
  match landing right after a `/`.
- **Landing** (`jumpToPath`, `update.go`) does not walk anything: it
  computes, in one shot, the `currentPath`/`navigationStack` that manually
  drilling down to the target's parent would have built one `navigateIn`
  step at a time, then requests that listing with the target queued for
  selection by absolute path (`pendingSelectPath`) once it loads — a listing
  is read in whatever order the filesystem gives it, so the row is found by
  path rather than assumed to land at a particular index.

**The query lives in the footer's bar slot, not the viewport.** `FuzzyFinder`
splits the same way the document viewer's `g` does: `View()` is the ranked
results table — the whole viewport, since a list needs real space — and
`RenderBar` draws the query through `components.BarFrame`, the identical
frame the "/" filter and the viewer's `renderGotoBar` already use, so the
rectangle that closes the viewport is the same one whichever of the three is
in it. `GetFooterHeight()` answers 4 while the mode is active (the bar's own
2 lines plus the usual empty-line-and-info-line), and the router notices the
change after the `g` keypress and re-lays-out on its own
(`app.forwardToActiveView`) — nothing here has to ask for it.

`g` is a lowercase, view-local binding (`keymap.localToggles`), the same
mechanism the document viewer's own `g` — "go to line" — already uses, and
for the same reason: the jump takes an argument, which is not a role
`home`/`end`/an uppercase action could cover. Uppercase `G` already means
"pull" elsewhere in the application (`oci_resources`) and stays that; this
is a different letter's case, not a second meaning for the same one.
