// Run is one batch of work, started in one go from one view.
type Run struct {
	ID   JobID
	Kind Kind
	// Origin is the view that started the run: where `:jobs` sends the user
	// back, and what decides whether a footer keeps its detailed line (D9).
	Origin command.ViewType
	// Context is stamped at launch and never re-read. It is what lets `:jobs`
	// filter on the current context instead of purging on a switch — which
	// would contradict keeping runs for the session (D8) — and it is what stops
	// a batch outliving a context switch from writing its results into the
	// wrong cache.
	Context string
	// Label names the run for a human: "~/work/perso", "nexus.example.com/team".
	Label     string
	Items     []Item
	StartedAt time.Time
	EndedAt   time.Time

	// cancelled records that someone asked for this run to stop. Without it a
	// cancelled run reads as done once its items settle, and a jobs view that
	// cannot tell "finished" from "you stopped it" is missing the one fact the
	// user is looking for.
	cancelled bool

	// open says the target list is still being discovered (D3). An open run is
	// never finished, however its items stand: a clone whose walk has found
	// three repositories and cloned all three is not done — the walk is still
	// going, and settling it there would stop the spinner chain and print a
	// summary the next repository contradicts.
	//
	// Every other kind knows its full list when it is admitted, which is what
	// makes "8 waiting" sayable at all (D10). The clone is the exception
	// because its walk *is* the work that finds them.
	open bool

	// cancel stops the run's queue. Cleared by Snapshot, like Item.cancel.
	cancel context.CancelFunc
}

// NewRun builds a run with every target queued. StartedAt is left to the
// registry, which stamps it when the run is admitted.
func NewRun(kind Kind, origin command.ViewType, contextName, label string, targets ...string) Run {
	items := make([]Item, len(targets))
	for i, target := range targets {
		items[i] = Item{Target: target, State: ItemQueued}
	}
	return Run{
		Kind:    kind,
		Origin:  origin,
		Context: contextName,
		Label:   label,
		Items:   items,
	}
}

// NewOpenRun builds a run whose targets are not known yet.
//
// It is the clone's shape and only the clone's: the walk that discovers
// repositories is itself the slow part, so a run that waited for the full list
// would show nothing for the minutes that matter. Targets arrive through
// Registry.Discover, and Registry.Seal says there will be no more.
func NewOpenRun(kind Kind, origin command.ViewType, contextName, label string) Run {
	return Run{
		Kind:    kind,
		Origin:  origin,
		Context: contextName,
		Label:   label,
		open:    true,
	}
}

// Open reports whether the run is still discovering its targets.
func (r Run) Open() bool { return r.open }

// WithDisplay names how one target should be printed. It is separate from
// NewRun because only some kinds have one — an image reference goes through a
// registry alias, a repository path does not.
func (r Run) WithDisplay(target, display string) Run {
	items := make([]Item, len(r.Items))
	copy(items, r.Items)
	for i := range items {
		if items[i].Target == target {
			items[i].Display = display
		}
	}
	r.Items = items
	return r
}

// State derives where the run stands from its items.
//
// The order of the three settled answers is the order in which they matter: a
// run that was cancelled reads cancelled even though its items failed for that
// very reason, and one failure is enough to make the whole run a failure.
func (r Run) State() RunState {
	var running, terminal, failed int
	for _, item := range r.Items {
		switch {
		case item.State == ItemRunning:
			running++
		case item.State.Terminal():
			terminal++
			if item.State == ItemFailed {
				failed++
			}
		}
	}

	// An open run is unsettled whatever its items say: more of them are coming.
	if r.open || terminal < len(r.Items) {
		if running > 0 || terminal > 0 {
			return RunRunning
		}
		return RunQueued
	}

	switch {
	case r.cancelled:
		return RunCancelled
	case failed > 0:
		return RunFailed
	default:
		return RunDone
	}
}

// Finished reports whether every item has settled. An empty *sealed* run is
// finished: there is nothing left for it to do, and reporting it as running
// would leave the spinner chain alive forever. An empty *open* one is not — it
// has found nothing yet, which is where every clone starts.
func (r Run) Finished() bool {
	state := r.State()
	return state != RunRunning && state != RunQueued
}

// Cancelled reports whether the run was asked to stop, whether or not its items
// have settled yet.
func (r Run) Cancelled() bool { return r.cancelled }

// Total is the first half of the "3/12" a footer prints.
func (r Run) Total() int { return len(r.Items) }

// Done is the second half. Both are derived rather than counted alongside,
// which is what removes the need for a scanRun struct beside the existing
// syncRun — the two were the same pair of integers maintained by hand.
//
// It counts the items that have settled, whichever way they settled: a skipped
// repository and a failed one are both finished with, which is what a progress
// line reports on.
func (r Run) Done() int {
	n := 0
	for _, item := range r.Items {
		if item.State.Terminal() {
			n++
		}
	}
	return n
}

// Stoppable reports whether asking this run to stop would change anything.
//
// It is D7 read as a question about *this* run rather than about its kind,
// which is what a view needs to decide whether to offer the key (Rule 130):
//
//   - a settled run has nothing left to stop;
//   - a kind whose work can be cut always has something — whatever is in flight;
//   - a run still discovering has its walk to stop, even with nothing queued;
//   - anything else can still have its queue stopped, if there is a queue.
//
// A delete falls through all four while it runs: one item, in flight, of a kind
// that must never be cut. That is the case the key is greyed for, and it is the
// reason this is a method rather than `!Finished()`. A create answers the same
// way and for the same reason.
func (r Run) Stoppable() bool {
	switch {
	case r.Finished():
		return false
	case r.Kind.Cancellable(), r.open:
		return true
	}
	for _, item := range r.Items {
		if item.State == ItemQueued {
			return true
		}
	}
	return false
}

// ItemStoppable reports whether one target can be stopped on its own.
//
// Narrower than Stoppable on purpose: stopping the run stops its queue whatever
// the kind, but cutting one target in flight is only offered where cutting
// leaves nothing behind (Kind.Cancellable). A half-written clone is the case
// that decides it.
func (r Run) ItemStoppable(item Item) bool {
	return !item.State.Terminal() && r.Kind.Cancellable()
}

// Counts returns how many items sit in each state, for a view that wants to say
// more than "3/12".
func (r Run) Counts() map[ItemState]int {
	out := make(map[ItemState]int, 5)
	for _, item := range r.Items {
		out[item.State]++
	}
	return out
}

// FilterContext keeps the runs stamped with the given context.
//
// It is a function over a snapshot rather than a second registry method: the
// snapshot is what travels in the message, so this is where every view that
// needs the filter already has the data (D8).
func FilterContext(runs []Run, contextName string) []Run {
	out := make([]Run, 0, len(runs))
	for _, run := range runs {
		if run.Context == contextName {
			out = append(out, run)
		}
	}
	return out
}

// Unfinished keeps the runs that are still going.
func Unfinished(runs []Run) []Run {
	out := make([]Run, 0, len(runs))
	for _, run := range runs {
		if !run.Finished() {
			out = append(out, run)
		}
	}
	return out
}
package jobs

import (
	"context"

	tea "github.com/charmbracelet/bubbletea"
)

// StartMsg asks the router to register a run and then dispatch the work that
// fills it.
//
// The view builds the run — it is the only place that knows the targets — and
// the router admits it, stamps it with the current context and starts the work
// (D10). Registration happens in Update, never inside a Cmd (Rule 110).
//
// Work rides on the message rather than being batched beside it because the
// order matters: a transition naming a run the registry has not admitted yet is
// refused, and a tea.Batch gives no order. The router is the sequencer, which
// is a smaller thing to get right than a Sequence at every launch site — and it
// leaves the work runnable only by the router, so a test can read what was
// launched without launching it.
type StartMsg struct {
	Run Run

	// Work is a builder rather than a command because the context is stamped
	// by the router, one step after the view has described the run (D8). Work
	// that writes into a context-scoped cache needs that name, and reading it
	// back from the configuration inside the command is the defect the stamp
	// exists to close: a batch outliving a context switch wrote its last
	// results into the cache of the context it had switched to.
	//
	// It is never nil for a run with work: Start passes a builder that ignores
	// the name, so a launch site that has no use for it reads as it did.
	Work func(contextName string) tea.Cmd

	// Cancel stops the run's queue, and is nil for the kinds that have nothing
	// to stop. It travels here rather than arriving later like an item's cancel
	// because a progressive run owns its context from the launch: the pipeline
	// is started in Update, so the function exists before the run is admitted.
	Cancel context.CancelFunc

	// Invocation names the MCP call that asked for this run, and is empty when
	// a person pressed a key (§3.61).
	//
	// It travels on the message rather than being matched by time: a router
	// that remembered "an invocation is in flight" and gave its identifier to
	// the next StartMsg would have a window of one Update cycle, in which a
	// keypress can land — and the agent would be handed the identifier of the
	// scan the user just started by hand. It is the shape of Run.Context: a
	// fact carried by what it is about, decided once.
	Invocation string
}

// WithInvocation stamps the run a jobs.Start* command is about to register with
// the call that asked for it.
//
// A decorator rather than a fourth constructor: Start, StartInContext and
// StartCancellable already differ along two axes, and an invocation-carrying
// variant of each would be six. A view's MCP handler wraps the command it was
// already returning, at the one place that knows who asked.
//
// An empty invocation returns the command untouched, so a keyboard launch pays
// nothing and reads as it did.
func WithInvocation(invocation string, cmd tea.Cmd) tea.Cmd {
	if invocation == "" || cmd == nil {
		return cmd
	}
	return func() tea.Msg {
		msg := cmd()
		start, ok := msg.(StartMsg)
		if !ok {
			return msg
		}
		start.Invocation = invocation
		return start
	}
}

// RefusedMsg says an invocation will not produce a run, and why.
//
// It is the sibling of StartMsg and lives beside it for that reason: between
// them they are everything an invocation can come to. A keypress needs no such
// message — the view puts the same sentence in its footer (Rule 130) — which is
// why Refuse returns nil for an empty invocation rather than a message nobody
// would route.
//
// Reason is the view's own Availability.Reason, so the sentence an agent reads
// is the one the header greys with and the footer prints. One calculation,
// three readers.
type RefusedMsg struct {
	Invocation string
	Reason     string
}

// Refuse builds the message, or nothing at all for a keyboard launch.
func Refuse(invocation, reason string) tea.Cmd {
	if invocation == "" {
		return nil
	}
	return func() tea.Msg {
		return RefusedMsg{Invocation: invocation, Reason: reason}
	}
}

// Start builds the message for work that does not depend on the context.
func Start(run Run, work tea.Cmd) tea.Cmd {
	return StartInContext(run, func(string) tea.Cmd { return work })
}

// StartCancellable builds the message for a run whose queue can be stopped —
// today the clone, whose pipeline is launched from Update and hands back its
// context there and then.
func StartCancellable(run Run, work tea.Cmd, cancel context.CancelFunc) tea.Cmd {
	return func() tea.Msg {
		return StartMsg{
			Run:    run,
			Work:   func(string) tea.Cmd { return work },
			Cancel: cancel,
		}
	}
}

// CancelOpenMsg asks the router to stop the open run of a kind (D3, D7).
//
// A kind rather than an identifier: a progressive run belongs to a screen that
// owns the display while it goes, so there is one at a time and the view can
// name it without holding a JobID — which is the registry state D1 keeps out of
// views.
type CancelOpenMsg struct {
	Kind Kind
}

// CancelOpen builds the message.
func CancelOpen(kind Kind) tea.Cmd {
	return func() tea.Msg { return CancelOpenMsg{Kind: kind} }
}

// CancelMsg asks the router to stop a run by identifier (D7).
//
// An identifier here, where CancelOpenMsg names a kind, and the difference is
// which view is asking. A launch site cannot hold a JobID — it would have to
// before the registry allocated one — but `:jobs` reads the identifier out of
// the snapshot it is already rendering, which is the run the cursor is on.
type CancelMsg struct {
	ID JobID
}

// Cancel builds the message.
func Cancel(id JobID) tea.Cmd {
	return func() tea.Msg { return CancelMsg{ID: id} }
}

// CancelItemMsg asks the router to stop one target of a run.
type CancelItemMsg struct {
	ID     JobID
	Target string
}

// CancelItem builds the message.
func CancelItem(id JobID, target string) tea.Cmd {
	return func() tea.Msg { return CancelItemMsg{ID: id, Target: target} }
}

// StartInContext builds the message for work that writes into a context-scoped
// cache. The builder is called once, in Update, with the name the router
// stamped on the run — so every command it returns carries that name however
// long the batch runs.
func StartInContext(run Run, work func(contextName string) tea.Cmd) tea.Cmd {
	return func() tea.Msg { return StartMsg{Run: run, Work: work} }
}

// ChangedMsg carries what the registry holds to every view that might show it.
// It is the whole of the broadcast (D1): a view keeps its own copy of a
// snapshot rather than reading a pointer the router writes, so nothing is read
// from View() while something else is writing it.
//
// It is sent on two occasions, and they are different in nature: a transition —
// something actually happened — and a spinner tick, where only the frame moved.
// The receiver does not have to tell them apart, which is why there is one
// message and not two.
//
// It lives in this package rather than in the router's so that every view can
// name it without importing the router, which imports them.
type ChangedMsg struct {
	// Runs is a copy, oldest first, every context included. Filtering on the
	// current one is the view's business (D8, FilterContext).
	Runs []Run

	// Frame is the current spinner frame, bare — no escape sequence. Rule 122:
	// a table cell is measured before it is styled, so a styled frame of seven
	// visible cells measures twenty-eight and is truncated inside its own
	// escape, which then bleeds down the rest of the table.
	Frame string

	// RenderedFrame is the same frame styled, which is what a footer takes
	// (Rule 128 — measurement there goes through lipgloss.Width, which ignores
	// escapes). The router fills both so the two readings of one frame cannot
	// drift, and so this package needs to know nothing about styling.
	RenderedFrame string
}

// Running counts the runs in the snapshot that have not settled. It saves every
// receiver the same three lines.
func (m ChangedMsg) Running() int {
	return len(Unfinished(m.Runs))
}

package app

import (
	"time"

	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// changedMsg is the snapshot the router broadcasts. It fills both readings of
// the frame — bare for a table cell (Rule 122), styled for a footer
// (Rule 128) — so the two cannot drift and internal/jobs needs to know nothing
// about styling.
func (a *App) changedMsg() jobs.ChangedMsg {
	frame := a.jobFrame()
	return jobs.ChangedMsg{
		Runs:          a.jobs.Snapshot(),
		Frame:         frame,
		RenderedFrame: theme.SpinnerStyle().Render(frame),
	}
}

// handleStartJobs admits a run a view built and asks the registry for it.
//
// The context is stamped here rather than by the view: the router is what knows
// which context is current, and a view reading it back from the configuration
// would be reading it again — which is the shape of the defect the stamp exists
// to close (a batch outliving a switch and writing into the new context's
// cache).
//
// The stamp is then handed to the work, which is the half that was missing
// (D68): a run carrying the right name while its commands re-read the current
// one told `:jobs` the truth and wrote the cache anyway. Building the work here
// means the name is read once, in Update, and every command of the batch shares
// the string — a switch three repositories later cannot reach it.
func (a *App) handleStartJobs(msg jobs.StartMsg) (tea.Model, tea.Cmd) {
	run := msg.Run
	run.Context = a.currentContext
	id := a.jobs.Start(run)
	if msg.Cancel != nil {
		a.jobs.AttachRun(id, msg.Cancel)
	}
	// The identifier exists here and nowhere else, which is why an MCP call
	// waiting for one is answered from this handler (§3.61).
	a.settleInvocation(msg.Invocation, id, nil)
	// The work goes out after the registration, which is the whole reason it
	// travels on the message: a transition naming a run the registry has not
	// admitted yet is refused, and the row would spin for the life of the view.
	cmds := []tea.Cmd{a.jobsChanged()}
	if msg.Work != nil {
		cmds = append(cmds, msg.Work(run.Context))
	}
	return a, tea.Batch(cmds...)
}

// routeWork applies a progress message to the registry and hands it to the view
// that owns it.
//
// The registry is written **before** the view sees the message, so the view is
// reading a current snapshot when it handles it — which is what lets it ask
// "has my batch finished?" rather than counting alongside.
//
// A message that reports on work nobody registered is still routed: the view
// has its own reasons to see it, and Apply already returned false rather than
// inventing a run for it.
func (a *App) routeWork(target command.ViewType, msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmds []tea.Cmd
	if reporter, ok := msg.(jobs.Reporter); ok {
		if a.jobs.Apply(reporter.Transition()) {
			cmds = append(cmds, a.jobsChanged())
		}
	}
	// A sealer says a progressive run has found everything it is going to
	// (D3). It is a second interface because sealing names no target — the
	// message carrying it is a closed channel, and there is nothing for it to
	// be about.
	if sealer, ok := msg.(jobs.Sealer); ok {
		if a.jobs.Seal(sealer.Seal()) {
			cmds = append(cmds, a.jobsChanged())
		}
	}
	_, cmd := a.routeToView(target, msg)
	return a, tea.Batch(append(cmds, cmd)...)
}

// handleCancelOpen stops the open run of a kind and tells every view.
//
// The view that asked is updated by the broadcast like any other, so it does
// not have to keep its own idea of "cancelling" in step with the registry's.
func (a *App) handleCancelOpen(msg jobs.CancelOpenMsg) (tea.Model, tea.Cmd) {
	if !a.jobs.CancelOpen(msg.Kind) {
		return a, nil
	}
	return a, a.jobsChanged()
}

// handleCancel stops a run named by identifier, and handleCancelItem one of its
// targets (D7).
//
// The identifier comes from the snapshot the asking view is rendering, which is
// what makes it addressable at all: a launch site could not hold one — it would
// have to before the registry allocated it — but `:jobs` reads it off the row
// the cursor is on.
//
// A refusal is silent here, and it is not a swallowed error: the view asked
// only because its own guard said it could (Rule 130), so a false answer means
// the run settled between the keypress and this handler. There is nothing to
// tell the user that the next broadcast will not say better.
func (a *App) handleCancel(msg jobs.CancelMsg) (tea.Model, tea.Cmd) {
	if !a.jobs.Cancel(msg.ID) {
		return a, nil
	}
	return a, a.jobsChanged()
}

func (a *App) handleCancelItem(msg jobs.CancelItemMsg) (tea.Model, tea.Cmd) {
	if !a.jobs.CancelItem(msg.ID, msg.Target) {
		return a, nil
	}
	return a, a.jobsChanged()
}

// jobTickMsg advances the one spinner frame the whole application shares.
//
// It is the router's own message type rather than a spinner.TickMsg on purpose.
// bubbles keeps chains apart with an id and a tag, which works, but it means a
// stray tick from any view is something this handler would have to recognise
// and decline. A message nobody else sends cannot be confused with anything.
type jobTickMsg struct {
	// seq identifies the chain. A tick from an older one is dropped, which is
	// what makes a second chain impossible rather than merely unlikely — the
	// failure the four hand-stamped spinners kept producing was two chains
	// advancing the same frame at twice the rate.
	seq int
}

// jobSpinnerInterval is the cadence of the shared frame. It is taken from the
// same spinner the views used, so the animation does not change speed on the
// day a view stops stamping its own.
//
// It is a var rather than a const for one reason: testutil.FastTimers shortens
// it for the length of a test, the way components.FooterMsgDuration is. A test
// that drains the chain would otherwise sleep a tenth of a second per tick.
var jobSpinnerInterval = spinner.Dot.FPS

func jobTick(seq int) tea.Cmd {
	return tea.Tick(jobSpinnerInterval, func(time.Time) tea.Msg {
		return jobTickMsg{seq: seq}
	})
}

// jobFrame returns the current bare frame.
func (a *App) jobFrame() string {
	frames := spinner.Dot.Frames
	return frames[a.jobFrameIdx%len(frames)]
}

// jobsChanged is what a launch site or a transition calls once it has written
// to the registry: it tells every view, and makes sure the frame is moving.
//
// Both halves are needed and neither implies the other — a run that starts
// while another is already going changes the snapshot without needing a second
// chain, and a run that settles changes the snapshot while the chain must be
// allowed to die.
func (a *App) jobsChanged() tea.Cmd {
	return tea.Batch(a.broadcastJobs(), a.ensureJobTick())
}

// broadcastJobs hands the current snapshot to every view the router holds, on
// screen or not.
//
// Every view and not just the active one: a view is updated where it stands so
// that coming back to it shows what happened while it was away, without it
// having to ask. The cost is one Update per held view per frame, and a view's
// Update returns on the first type switch for a message it does not know.
//
// The layout is re-measured once at the end rather than per view, for the same
// reason forwardToActiveView measures at all: a footer that grew a line has to
// be given it (Rule 124). Only the view on screen can change the height, so one
// check covers the loop.
func (a *App) broadcastJobs() tea.Cmd {
	msg := a.changedMsg()

	cmds := make([]tea.Cmd, 0, len(a.views))
	for name, view := range a.views {
		updated, cmd := view.Update(msg)
		a.views[name] = updated
		if cmd != nil {
			cmds = append(cmds, cmd)
		}
	}

	if newFooterHeight := a.getFooterHeight(); newFooterHeight != a.lastFooterHeight {
		a.resize(a.width, a.height)
	}
	return tea.Batch(cmds...)
// Transition is what a progress message says about one target.
//
// It exists so the router can apply a message without knowing the vocabulary of
// the view that sent it. A sync that was refused because the tree is dirty is a
// skip with a reason; only the workspaces package knows that, and it says so by
// answering this — see Reporter.
type Transition struct {
	Kind   Kind
	Target string
	State  ItemState
	Detail string

	// Cancel stops the work this transition reports as started, and is nil for
	// every other transition and for the kinds that cannot be cut (D7).
	//
	// It travels on the transition rather than through a call of its own
	// because the two are one event: the context is created inside the Cmd, so
	// the function reaches Update in the message that says the item started.
	Cancel context.CancelFunc

	// Discover says the target has no row yet and belongs to the open run of
	// this kind (D3). Only a kind whose targets arrive progressively sets it —
	// the clone, whose walk is what finds them — and for every other kind it
	// stays false because the full list was known at launch.
	Discover bool
}

// Reporter is implemented by a message that reports on registered work.
//
// The alternative was a switch in the router mapping every view's outcome
// vocabulary onto item states, which puts each view's semantics in a file that
// belongs to none of them, and grows by one branch per view.
type Reporter interface {
	Transition() Transition
}

// Sealer is implemented by the message that says a kind's open run has found
// everything it is going to (D3).
//
// It is a second interface rather than a field on Transition because sealing
// names no target: the message that carries it is the closed event channel, and
// there is nothing for it to be about.
type Sealer interface {
	Seal() Kind
}

// Apply routes a transition to the run it belongs to. It reports whether one
// was found, which is how the router knows there is something new to broadcast.
func (r *Registry) Apply(t Transition) bool {
	if t.Discover {
		return r.Discover(t.Kind, t.Target, t.State, t.Detail)
	}
	id, ok := r.FindItem(t.Kind, t.Target)
	if !ok {
		return false
	}
	return r.advance(id, t.Target, t.State, t.Detail, t.Cancel)
}

// Discover adds a target to the open run of a kind (D3).
//
// A target already there is advanced instead of duplicated: the walk reports a
