// D7 is a table, and a kind added without an entry in it would silently answer
// "not cancellable" — the safe answer, which is exactly why nothing would ever
// notice. Walking Kinds() makes the omission a compile-time-shaped question
// instead.
func TestEveryKindAnswersWhetherItCanBeCancelled(t *testing.T) {
	want := map[Kind]bool{
		KindScan:   true,
		KindPull:   true,
		KindSync:   false,
		KindClone:  false,
		KindCreate: false,
		KindDelete: false,
	}

	kinds := Kinds()
	if got, expected := len(kinds), len(want); got != expected {
		t.Fatalf("Kinds() returns %d kinds, want %d — the D7 table is out of step", got, expected)
	}
	for _, kind := range kinds {
		expected, declared := want[kind]
		if !declared {
			t.Errorf("kind %q is not in the D7 cancellation table", kind)
			continue
		}
		if got := kind.Cancellable(); got != expected {
			t.Errorf("%q.Cancellable() = %v, want %v", kind, got, expected)
		}
	}
}
)

// stopRefusal names why a run cannot be stopped, in the run's own words.
//
// The wording is per kind because the reason is: a delete in flight must never
// be cut, and saying so with the verb the row already shows is what makes the
// greyed key readable without opening the help.
func stopRefusal(kind jobs.Kind) string {
	return "A " + string(kind) + " cannot be stopped once it has started"
}

// availability is what the selected row and the current level permit, computed
// once and read by both halves of the view.
//
// One field per key rather than a bool and a string apart: an empty reason
// means available, so the two cannot disagree.
type availability struct {
	Open  shortcut.Availability
	Close shortcut.Availability
	Sort  shortcut.Availability
	Stop  shortcut.Availability

		t.Errorf("Count(0) = %v, want a pointer to 0 — a counted zero is an answer", stats.AssignedIssues)
	}
}

