package explorer

import (
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/shared"
	"github.com/anthnel/devdesk/internal/template"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// ViewMode represents the current mode of the view
type ViewMode int

const (
	ModeNormal ViewMode = iota
	// ModeSelecting is the clone selection: the same tree, with a checkbox on
	// every row and `Space` ticking it (§3.16, decision 8).
	ModeSelecting
	// ModeCloning is the discovery-and-clone pipeline: a flat list of what has
	// been found, each row carrying its own state. It replaced the modal that
	// said "Pulling..." for however many minutes the subtree took (decision 9).
	ModeCloning
	ModeCreatingProject
	ModeConfirmingDelete
)

// Model represents the model of the GitLab Explorer view
func (m Model) InEditMode() bool {
	return m.creationForm != nil || m.mode != ModeNormal || m.table.InEditMode()
}

// FilterBarVisible returns true when the filter bar is visible (implements app.FilterBarView).
func (m Model) FilterBarVisible() bool {
	if m.mode == ModeCloning && m.clone != nil {
		return m.clone.table.FilterBar().IsVisible()
	}
	return m.showsTree() && m.table.FilterBar().IsVisible()
}

// tabCount returns the total number of tabs (home + navigation stack + current group)
func (m Model) tabCount() int {
	count := 1 // home tab
	for _, node := range m.navigationStack {
		if node != nil {
			count++
		}
	}
	if m.currentGroupNode != nil {
		count++
	}
	return count
}

// resize adjusts table dimensions based on terminal size
func (m *Model) resize(width, height int) {
	// Rule 124: the footer (tab bar + filter bar) is outside the viewport, so
	// only the table's own header row is subtracted. The Rule 116 arithmetic is
	// the component's — seven ratios and a remainder used to live here.
	m.table.Resize(width, max(height-1, 1))
	if m.clone != nil {
		m.clone.table.Resize(width, max(height-1, 1))
	}
}
//
// A prediction, because the forge answers with the real one and is free to
// differ — but the row has to exist before there is an answer, so it needs a
// key that can be computed now. settleCreating is what reconciles the two.
func (m Model) createTarget(msg components.CreationFormSubmitMsg) string {
	slug := slugify(msg.Name)
	if m.creationParentName == "" {
		return slug
	}
	return m.creationParentName + "/" + slug
}

// insertCreatingNode puts the placeholder at the level being browsed.
//
// At the end of the level rather than sorted in: the default is the forge's own
// order, which is insertion order, so the row appears where a reader's eye is
// free — the bottom — instead of displacing rows above the cursor. Under a sort
// the table places it like any other row.
// replaceCreating swaps the placeholder keyed on target for what the forge
// answered, or drops it when replacement is nil.
//
// It walks the loaded tree rather than the current level: the user is free to
// drill elsewhere while the request is in flight, and the row belongs to the
// level it was made in.
func replaceCreating(nodes []*TreeNode, target string, replacement *TreeNode) ([]*TreeNode, bool) {
	for i, node := range nodes {
		if node.Creating && node.FullPath == target {
			if replacement == nil {
				return append(nodes[:i], nodes[i+1:]...), true
			}
			replacement.Parent = node.Parent
			nodes[i] = replacement
			return nodes, true
		}
		if children, ok := replaceCreating(node.Children, target, replacement); ok {
			node.Children = children
			return nodes, true
		}
	}
	return nodes, false
}

// carryOverCreating keeps the placeholders of a level that is being replaced.
//
// A reload swaps the level wholesale — `ctrl+r` at the root, a ChildrenLoadedMsg
// inside a group — and a create still in flight has nothing yet to be replaced
// by. Dropped here, its row would vanish mid-request while the registry went on
// tracking the run: `:jobs` would show work the tree had stopped admitting to,
// and settleCreating would have nothing left to resolve when the answer came.
	out := make([]string, 0, len(s.roots))
	for p := range s.roots {
		out = append(out, p)
	}
	return out
}

// parentPath drops the last segment, returning "" at the top.
func parentPath(path string) string {
	if i := strings.LastIndex(path, "/"); i > 0 {
		return path[:i]
	}
	return ""
}

// hasDescendant reports whether the set holds anything strictly below path.
// The trailing separator is what keeps "acme/platform-tools" from counting as a
// descendant of "acme/platform".
func hasDescendant(set map[string]bool, path string) bool {
	prefix := path + "/"
	for p := range set {
		if strings.HasPrefix(p, prefix) {
			return true
		}
	}
	return false
}

